  grossMargin: string;
  /** Margin as percent of base price, e.g. "64.32" */
  marginPct: string;
  /** Food cost as percent of base price, e.g. "24.10" */
  foodCostPct: string;
  costDeviation: string | null;
  /** "food_cost_high" | "margin_low" | null */
